// ─── File: CachingDemo.java ───
package com.bank.caching;

import java.util.logging.*;

public class CachingDemo {
    private static final Logger log = Logger.getLogger("Cache");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        Database db = new Database();
        db.save("balance:SAV2001", "1000000");
        db.save("fd:rate", "7.5");
        Cache cache = new Cache();
        CacheStrategies s = new CacheStrategies(cache, db);

        // 1. Cache-aside read: miss then hit
        log.info(() -> "aside1 " + s.cacheAsideRead("balance:SAV2001"));
        log.info(() -> "aside2 " + s.cacheAsideRead("balance:SAV2001"));

        // 2. Write-through on a transfer: cache stays consistent
        s.writeThrough("balance:SAV2001", "950000");
        log.info(() -> "after write-through " + s.cacheAsideRead("balance:SAV2001"));

        // 3. Write-behind an analytics counter (tolerant data)
        s.writeBehind("views:fd-offer", "1");

        // 4. Event-based invalidation on rate change
        db.save("fd:rate", "7.75");
        s.invalidate("fd:rate");

        // 5. Stampede: hot key expired, 3 concurrent reads → one rebuild
        Runnable r = () -> log.info(() -> Thread.currentThread().getName()
            + " fd:rate=" + s.readWithStampedeGuard("fd:rate"));
        Thread t1 = new Thread(r, "T1"), t2 = new Thread(r, "T2"), t3 = new Thread(r, "T3");
        t1.start(); t2.start(); t3.start();
        t1.join(); t2.join(); t3.join();
    }
}

