```java
// ─── File: CacheStrategies.java ───
package com.bank.caching;

import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import java.util.logging.*;

public class CacheStrategies {
    private static final Logger log = Logger.getLogger("Cache");
    private final Cache cache;
    private final Database db;
    private final ExecutorService async = Executors.newSingleThreadExecutor();
    private final ConcurrentHashMap<String, Lock> locks = new ConcurrentHashMap<>();

    public CacheStrategies(Cache cache, Database db) { this.cache = cache; this.db = db; }

    // 1. cache-aside (lazy load)
    public String cacheAsideRead(String key) {
        String v = cache.get(key);
        if (v != null) { log.info(() -> "HIT " + key); return v; }
        v = db.load(key);
        cache.put(key, v);
        return v;
    }

    // 2. write-through (DB + cache together)
    public void writeThrough(String key, String value) {
        db.save(key, value);
        cache.put(key, value);
        log.info(() -> "write-through " + key + "=" + value);
    }

    // 3. write-behind (cache now, DB async)
    public void writeBehind(String key, String value) {
        cache.put(key, value);
        async.submit(() -> db.save(key, value));
        log.info(() -> "write-behind cached " + key + ", DB flush queued");
    }

    // 4. event-based invalidation
    public void invalidate(String key) {
        cache.evict(key);
        log.warning(() -> "invalidated " + key);
    }

    // 5. stampede prevention via single-flight
    public String readWithStampedeGuard(String key) {
        String v = cache.get(key);
        if (v != null) return v;
        Lock lock = locks.computeIfAbsent(key, k -> new ReentrantLock());
        lock.lock();
        try {
            v = cache.get(key);                 // double-check
            if (v != null) { log.info(() -> "served by waiter " + key); return v; }
            log.info(() -> "single rebuild " + key);
            v = db.load(key);                    // only ONE thread loads
            cache.put(key, v);
            return v;
        } finally { lock.unlock(); }
    }
}
```
